LANGS = ["en", "es", "fr", "de", "hi", "pt_BR"]

def main():
    root = Path(__file__).resolve().parent.parent / "_locales"
    for i, lang in enumerate(LANGS):
        out = {k: {"message": row[i]} for k, *row in [(r[0], *r[1:]) for r in KEYS]}
        d = root / lang
        d.mkdir(parents=True, exist_ok=True)
        (d / "messages.json").write_text(json.dumps(out, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"wrote {len(KEYS)} keys x {len(LANGS)} languages")

if __name__ == "__main__":
    main()
